import { DatabaseSync } from "node:sqlite";

const db = new DatabaseSync("zadachi.db");
db.exec("CREATE TABLE IF NOT EXISTS tasks (id INTEGER PRIMARY KEY, title TEXT NOT NULL)");

const insert = db.prepare("INSERT INTO tasks (title) VALUES (?)");
insert.run("Купи хляб");

const rows = db.prepare("SELECT id, title FROM tasks").all();
console.log("Редове:", rows.length, JSON.stringify(rows));
db.close();
